script:
(function () {
  'use strict';
  // Combination (piggyback) mortgage vs one loan with PMI, same price and same down payment.
  //   First = price x first%, second = price x second%; single loan = first + second.
  //   Each loan: fixed payment M = L x i / (1 - (1 + i)^-n), i = rate / 12 (L / n at 0%), balance rolled monthly.
  //   PMI = PMI rate x original single-loan amount / 12, charged in a month while the scheduled balance at the
  //   start of that month is above 78% (or 80%) of the price, and never after the loan's midpoint
  //   (Homeowners Protection Act termination rules). No PMI when the single loan is 80% of the price or less.
  //   Cost over N years = interest + PMI (+ second-mortgage closing costs). Principal repaid is not a cost.
  // Checked in Node (scratchpad tests/w3b3_cmb.test.js) against an independent Python amortization:
  //   $450,000, 80/10/10, 6.5% 30-yr first ($2,275.44) + 8.25% 15-yr second ($436.56) = $2,712.01;
  //   single $405,000 at 6.625% ($2,593.26) + $168.75 PMI = $2,762.01; PMI runs 111 months (until the
  //   balance first reaches $351,000); 10-year cost $247,039.11 vs $269,335.40 (difference $22,296); 0% rates,
  //   a 20%+ down payment (no PMI) and blank or invalid inputs never show NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var PRESETS = { '80-10-10': [80, 10], '80-15-5': [80, 15], '80-5-15': [80, 5] };

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(L, i, n) {
    if (L <= 0) return 0;
    if (i === 0) return L / n;
    return L * i / (1 - Math.pow(1 + i, -n));
  }

  // Month-by-month schedule: arrays indexed by month (0 = month 1) of interest, payment, PMI, end balance.
  function amortize(L, rate, years, pmi) {
    var i = rate / 100 / 12, n = years * 12, M = payment(L, i, n), b = L, rows = [], pmiMonths = 0;
    for (var m = 0; m < n; m++) {
      var interest = b * i, prem = 0;
      if (pmi && b > pmi.stopAt + 1e-6 && m < n / 2) { prem = pmi.monthly; pmiMonths++; }
      var principal = Math.min(b, M - interest);
      b = Math.max(0, b - principal);
      rows.push({ interest: interest, pay: interest + principal, pmi: prem, balance: b });
    }
    return { M: M, rows: rows, pmiMonths: pmiMonths };
  }

  function sumTo(s, months, key) {
    var t = 0;
    for (var m = 0; m < months && m < s.rows.length; m++) t += s.rows[m][key];
    return t;
  }
  function balanceAt(s, months, L) {
    if (months <= 0) return L;
    return months > s.rows.length ? 0 : s.rows[months - 1].balance;
  }

  function duration(months) {
    var y = Math.floor(months / 12), mo = months % 12;
    var parts = [];
    if (y) parts.push(y + (y === 1 ? ' yr' : ' yrs'));
    if (mo) parts.push(mo + (mo === 1 ? ' mo' : ' mos'));
    return parts.join(' ') || '0 mos';
  }

  function syncPreset(e) {
    var t = e && e.target ? e.target.id : '';
    if (t === 'cmbPreset') {
      var p = PRESETS[el('cmbPreset').value];
      if (p) { el('cmbFirstPct').value = String(p[0]); el('cmbSecondPct').value = String(p[1]); }
    } else if (t === 'cmbFirstPct' || t === 'cmbSecondPct') {
      var f = read('cmbFirstPct'), s = read('cmbSecondPct'), match = 'custom';
      Object.keys(PRESETS).forEach(function (k) { if (PRESETS[k][0] === f && PRESETS[k][1] === s) match = k; });
      el('cmbPreset').value = match;
    }
  }

  function signedMoney(x) { return (x < 0 ? '−' : '') + money0.format(Math.abs(x)); }

  function clearResults() {
    ['cmbDiff', 'cmbPayCombo', 'cmbPaySingle', 'cmbPmiEnds', 'cmbNote'].forEach(function (id) { setText(id, '–'); });
    el('cmbCompare').innerHTML = '';
    el('cmbYearsBody').innerHTML = '';
  }

  function update(e) {
    syncPreset(e);
    var price = read('cmbPrice'), fp = read('cmbFirstPct'), sp = read('cmbSecondPct', true),
        r1 = read('cmbRate1'), r2 = read('cmbRate2'), r = read('cmbRate'), pmiRate = read('cmbPmi', true),
        t1 = parseInt(el('cmbTerm1').value, 10), t2 = parseInt(el('cmbTerm2').value, 10), t = parseInt(el('cmbTerm').value, 10),
        years = read('cmbYears'), fees = read('cmbFees', true), stopPct = parseInt(el('cmbPmiEnd').value, 10);
    var error = el('cmbError'), msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a home price greater than $0.';
    else if (isNaN(fp) || isNaN(sp) || fp <= 0 || sp < 0) msg = 'Enter the first mortgage as more than 0% of the price, and the second as 0% or more.';
    else if (fp + sp > 100) msg = 'The two loans cannot add up to more than 100% of the price.';
    else if ([r1, r2, r].some(function (v) { return isNaN(v) || v < 0 || v > 30; })) msg = 'Enter interest rates from 0% to 30%.';
    else if (isNaN(pmiRate) || pmiRate < 0 || pmiRate > 5) msg = 'Enter a PMI rate from 0% to 5% a year.';
    else if (isNaN(years) || years < 1 || years > 30 || years % 1 !== 0) msg = 'Compare over 1 to 30 whole years.';
    else if (isNaN(fees) || fees < 0) msg = 'Closing costs cannot be negative.';
    var down = 100 - (isNaN(fp) ? 0 : fp) - (isNaN(sp) ? 0 : sp);
    setText('cmbDownNote', !isNaN(price) && price > 0 && down >= 0 && !isNaN(fp)
      ? 'Down payment: ' + (Math.round(down * 100) / 100) + '% (' + money0.format(price * down / 100) + ').' : '');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var L1 = price * fp / 100, L2 = price * sp / 100, L = L1 + L2;
    var hasPmi = L > 0.8 * price + 1e-6;
    var pmi = hasPmi ? { monthly: pmiRate / 100 * L / 12, stopAt: stopPct / 100 * price } : null;
    var a = amortize(L1, r1, t1, null), b = amortize(L2, r2, t2, null), s = amortize(L, r, t, pmi);
    var H = years * 12;

    var comboCost = function (m) { return sumTo(a, m, 'interest') + sumTo(b, m, 'interest') + (L2 > 0 ? fees : 0); };
    var singleCost = function (m) { return sumTo(s, m, 'interest') + sumTo(s, m, 'pmi'); };
    var cH = comboCost(H), sH = singleCost(H), diff = sH - cH;
    var full = Math.max(t1, t2, t) * 12;
    var cFull = comboCost(full), sFull = singleCost(full);

    var payCombo = a.M + b.M, paySingle = s.M + (pmi ? pmi.monthly : 0);
    var yrs = years + (years === 1 ? ' year' : ' years');
    setText('cmbDiffLabel', Math.abs(diff) < 0.5 ? 'Difference over ' + yrs : (diff > 0 ? 'Combination saves over ' : 'Single loan saves over ') + yrs);
    setText('cmbDiff', money0.format(Math.abs(diff)));
    setText('cmbPayCombo', money.format(payCombo));
    setText('cmbPaySingle', money.format(paySingle));
    setText('cmbPmiEnds', pmi ? duration(s.pmiMonths) : 'No PMI');

    var note;
    if (L2 <= 0) {
      note = 'With no second mortgage the two options are the same loan amount; only the rates and PMI differ.';
    } else if (!hasPmi) {
      note = 'A single loan of ' + pct(L / price) + ' of the price does not need PMI, so a second mortgage only helps if its terms beat the single loan’s rate.';
    } else {
      note = 'Over ' + yrs + ' the ' + (diff >= 0 ? 'combination' : 'single loan') + ' costs ' + money0.format(Math.abs(diff)) +
        ' less once interest' + (fees > 0 ? ', PMI and fees are' : ' and PMI are') + ' counted. ';
      note += 'PMI on the single loan runs for ' + duration(s.pmiMonths) + ' and adds ' + money0.format(sumTo(s, full, 'pmi')) + ' in total. ';
      note += 'The second mortgage’s higher rate costs most early on, while its balance is largest.';
    }
    setText('cmbNote', note);

    function bal(sched, m, amt) { return balanceAt(sched, m, amt); }
    var rows = [
      ['Loan amount', money0.format(L1) + ' + ' + money0.format(L2), money0.format(L)],
      ['Interest rate', r1 + '% / ' + r2 + '%', r + '%'],
      ['Monthly payment at the start', money.format(payCombo), money.format(paySingle)],
      ['PMI per month', '–', pmi ? money.format(pmi.monthly) : 'None'],
      ['Interest + PMI + fees over ' + years + ' yrs', money0.format(cH), money0.format(sH)],
      ['Owed after ' + years + ' yrs', money0.format(bal(a, H, L1) + bal(b, H, L2)), money0.format(bal(s, H, L))],
      ['Interest + PMI + fees, full terms', money0.format(cFull), money0.format(sFull)]
    ];
    el('cmbCompare').innerHTML = rows.map(function (row) {
      return '<tr><th scope="row">' + row[0] + '</th><td>' + row[1] + '</td><td>' + row[2] + '</td></tr>';
    }).join('');

    var out = [];
    for (var y = 1; y * 12 <= full; y++) {
      var m0 = (y - 1) * 12, m1 = y * 12;
      var cPaid = sumTo(a, m1, 'pay') - sumTo(a, m0, 'pay') + sumTo(b, m1, 'pay') - sumTo(b, m0, 'pay');
      var sPaid = sumTo(s, m1, 'pay') - sumTo(s, m0, 'pay') + sumTo(s, m1, 'pmi') - sumTo(s, m0, 'pmi');
      out.push('<tr><td>' + y + '</td><td>' + money0.format(cPaid) + '</td><td>' + money0.format(bal(a, m1, L1) + bal(b, m1, L2)) +
        '</td><td>' + money0.format(sPaid) + '</td><td>' + money0.format(bal(s, m1, L)) + '</td><td>' +
        signedMoney(singleCost(m1) - comboCost(m1)) + '</td></tr>');
    }
    el('cmbYearsBody').innerHTML = out.join('');
  }

  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('cmbForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
